def icon(name: str, size: int = 22, cls: str = "ic") -> str:
    """Инлайн-SVG иконки по имени. Неизвестное имя → пустая строка (не падаем)."""
    body = _BODIES.get(name)
    if body is None:
        return ""
    return (
        f"<svg class='{cls}' width='{size}' height='{size}' viewBox='{_VIEWBOX}' "
        f"aria-hidden='true' focusable='false'>{body}</svg>"
    )
